import { sqliteTable, text, integer } from "drizzle-orm/sqlite-core"

// Events table. Kept dialect-portable: only text/integer columns and the Drizzle
// query builder are used elsewhere, so moving to Postgres is a config + import
// change (drizzle-orm/pg-core) rather than a query rewrite.
//
// Dates are stored as ISO-8601 strings (text) rather than a DB-specific datetime
// type — portable across SQLite/libSQL and Postgres, and matches the wire format
// the client (useEventAPI) already sends/receives.
export const events = sqliteTable("events", {
  id: text("id").primaryKey(),
  // ownerId is nullable — set it when you add auth; left null in the single-user template.
  ownerId: text("owner_id"),
  title: text("title").notNull(),
  description: text("description"),
  startDate: text("start_date").notNull(), // ISO string
  endDate: text("end_date").notNull(), // ISO string
  startTime: text("start_time"),
  endTime: text("end_time"),
  allDay: integer("all_day", { mode: "boolean" }).notNull().default(false),
  color: text("color"),
  location: text("location"),
  status: text("status"),
  timezone: text("timezone"),
  isRecurring: integer("is_recurring", { mode: "boolean" }).notNull().default(false),
  recurringPattern: text("recurring_pattern"), // JSON string when present
  recurringId: text("recurring_id"),
  createdAt: text("created_at").notNull(),
  updatedAt: text("updated_at").notNull(),
})

// Users. Sessions are sealed cookies (nuxt-auth-utils) and need no table — this
// is the only auth table the app owns. Password auth stores only a scrypt hash.
export const users = sqliteTable("users", {
  id: text("id").primaryKey(),
  email: text("email").notNull().unique(),
  name: text("name"),
  passwordHash: text("password_hash").notNull(),
  createdAt: text("created_at").notNull(),
})

// Invites. When registration is invite-only (the default), a valid unused,
// unexpired invite token is required to register. Created by an existing user.
export const invites = sqliteTable("invites", {
  token: text("token").primaryKey(),
  email: text("email"), // optional: restrict the invite to a specific email
  createdBy: text("created_by").notNull(),
  usedBy: text("used_by"), // set to the new user's id once consumed
  expiresAt: text("expires_at"), // ISO string; null = no expiry
  createdAt: text("created_at").notNull(),
})

export type EventRow = typeof events.$inferSelect
export type NewEventRow = typeof events.$inferInsert
export type UserRow = typeof users.$inferSelect
export type NewUserRow = typeof users.$inferInsert
export type InviteRow = typeof invites.$inferSelect
export type NewInviteRow = typeof invites.$inferInsert

import { createClient, type Client } from "@libsql/client"
import { drizzle, type LibSQLDatabase } from "drizzle-orm/libsql"
import * as schema from "../db/schema"

// Single lazily-created libSQL client + Drizzle instance per server process.
// The connection URL/token come from runtimeConfig (runtime-configurable). For a
// self-hosted sqld with no auth, the token is empty and omitted.
let _client: Client | null = null
let _db: LibSQLDatabase<typeof schema> | null = null

export function useDb(): LibSQLDatabase<typeof schema> {
  if (_db) return _db

  const { libsql } = useRuntimeConfig()
  const url = libsql?.url
  if (!url) {
    throw createError({ statusCode: 500, statusMessage: "libSQL URL is not configured" })
  }

  _client = createClient(
    libsql.authToken ? { url, authToken: libsql.authToken } : { url },
  )
  _db = drizzle(_client, { schema })
  return _db
}

// Raw client — used by the health check for a lightweight connectivity probe.
export function useDbClient(): Client {
  useDb()
  return _client as Client
}

export { schema }

import { isValid, parseISO } from "date-fns"
import type { EventRow, NewEventRow } from "../db/schema"

// The wire shape of an event: same as the client's CalendarEvent but with dates
// as ISO strings (JSON has no Date type). useEventAPI sends/expects exactly this.
export interface EventDTO {
  id: string
  ownerId?: string | null
  title: string
  description?: string
  startDate: string
  endDate: string
  startTime?: string
  endTime?: string
  allDay?: boolean
  color?: string
  location?: string
  status?: string
  timezone?: string
  isRecurring?: boolean
  recurringPattern?: unknown
  recurringId?: string
}

// DB row -> wire DTO (client JSON).
export function rowToDto(row: EventRow): EventDTO {
  return {
    id: row.id,
    ownerId: row.ownerId,
    title: row.title,
    description: row.description ?? undefined,
    startDate: row.startDate,
    endDate: row.endDate,
    startTime: row.startTime ?? undefined,
    endTime: row.endTime ?? undefined,
    allDay: row.allDay,
    color: row.color ?? undefined,
    location: row.location ?? undefined,
    status: row.status ?? undefined,
    timezone: row.timezone ?? undefined,
    isRecurring: row.isRecurring,
    recurringPattern: row.recurringPattern ? safeParse(row.recurringPattern) : undefined,
    recurringId: row.recurringId ?? undefined,
  }
}

// Incoming create/update payload -> DB row columns. Only known fields are copied
// (unknown fields are ignored, never persisted). Returns a partial for updates.
export function dtoToRow(input: Partial<EventDTO>): Partial<NewEventRow> {
  const row: Partial<NewEventRow> = {}
  if (input.id !== undefined) row.id = input.id
  if (input.ownerId !== undefined) row.ownerId = input.ownerId
  if (input.title !== undefined) row.title = input.title
  if (input.description !== undefined) row.description = input.description
  if (input.startDate !== undefined) row.startDate = toISO(input.startDate)
  if (input.endDate !== undefined) row.endDate = toISO(input.endDate)
  if (input.startTime !== undefined) row.startTime = input.startTime
  if (input.endTime !== undefined) row.endTime = input.endTime
  if (input.allDay !== undefined) row.allDay = !!input.allDay
  if (input.color !== undefined) row.color = input.color
  if (input.location !== undefined) row.location = input.location
  if (input.status !== undefined) row.status = input.status
  if (input.timezone !== undefined) row.timezone = input.timezone
  if (input.isRecurring !== undefined) row.isRecurring = !!input.isRecurring
  if (input.recurringPattern !== undefined) {
    row.recurringPattern = input.recurringPattern ? JSON.stringify(input.recurringPattern) : null
  }
  if (input.recurringId !== undefined) row.recurringId = input.recurringId
  return row
}

function toISO(value: string): string {
  // Accept ISO strings and normalize to a canonical ISO timestamp; pass through
  // anything unparseable unchanged (validation rejects it separately).
  const parsed = parseISO(value)
  return isValid(parsed) ? parsed.toISOString() : value
}

function safeParse(json: string): unknown {
  try {
    return JSON.parse(json)
  } catch {
    return undefined
  }
}

import { isValid, parseISO } from "date-fns"
import type { EventDTO } from "./eventMapper"

export interface ValidationError {
  field: string
  message: string
}

// Server-side validation for event create/update payloads. This is the
// authoritative check — the client validates too, but the API never trusts it.
// `partial` allows update payloads that omit fields.
export function validateEventInput(
  input: Partial<EventDTO>,
  { partial = false }: { partial?: boolean } = {},
): ValidationError[] {
  const errors: ValidationError[] = []

  const hasTitle = input.title !== undefined
  if (!partial || hasTitle) {
    if (typeof input.title !== "string" || input.title.trim().length === 0) {
      errors.push({ field: "title", message: "Event title is required" })
    }
  }

  const hasStart = input.startDate !== undefined
  const hasEnd = input.endDate !== undefined

  if (!partial || hasStart) {
    if (!isValidDate(input.startDate)) {
      errors.push({ field: "startDate", message: "A valid start date is required" })
    }
  }
  if (!partial || hasEnd) {
    if (!isValidDate(input.endDate)) {
      errors.push({ field: "endDate", message: "A valid end date is required" })
    }
  }

  // End must be after start for non-all-day events, when both are present/valid.
  if (isValidDate(input.startDate) && isValidDate(input.endDate) && !input.allDay) {
    const start = parseISO(input.startDate as string)
    const end = parseISO(input.endDate as string)
    if (start >= end) {
      errors.push({ field: "endDate", message: "End time must be after start time" })
    }
  }

  return errors
}

function isValidDate(value: unknown): boolean {
  if (typeof value !== "string" || value.length === 0) return false
  return isValid(parseISO(value))
}

import { and, gte, lte } from "drizzle-orm"
import { events } from "../../db/schema"
import { rowToDto } from "../../utils/eventMapper"

// GET /api/events?start=&end=&page=&limit=
// Returns a paginated envelope: { data, total, page, limit, hasMore }.
// A row overlaps [start, end] when its start <= end AND its end >= start.
//
// AUTH: this template returns ALL events (single-user). To scope events per user,
// resolve the user here (e.g. `const { user } = await requireUserSession(event)`)
// and add `eq(events.ownerId, user.id)` to the conditions below.
export default defineEventHandler(async (event) => {
  const q = getQuery(event)
  const page = Math.max(1, Number.parseInt(String(q.page ?? "1"), 10) || 1)
  const limit = Math.min(500, Math.max(1, Number.parseInt(String(q.limit ?? "100"), 10) || 100))
  const start = typeof q.start === "string" ? q.start : undefined
  const end = typeof q.end === "string" ? q.end : undefined

  const db = useDb()

  const conditions = []
  // TODO(auth): scope to the current user — conditions.push(eq(events.ownerId, user.id))
  if (end) conditions.push(lte(events.startDate, end))
  if (start) conditions.push(gte(events.endDate, start))

  const where = conditions.length ? and(...conditions) : undefined

  const rows = await db
    .select()
    .from(events)
    .where(where)
    .limit(limit)
    .offset((page - 1) * limit)

  const total = await db.$count(events, where)

  return {
    data: rows.map(rowToDto),
    total,
    page,
    limit,
    hasMore: page * limit < total,
  }
})

import { randomUUID } from "node:crypto"
import { events } from "../../db/schema"
import { dtoToRow, rowToDto, type EventDTO } from "../../utils/eventMapper"
import { validateEventInput } from "../../utils/eventValidation"

// POST /api/events — create an event. Returns 201 with the persisted event.
export default defineEventHandler(async (event) => {
  // TODO(auth): require a session and set ownerId to the current user
  const body = await readBody<Partial<EventDTO>>(event)

  const errors = validateEventInput(body)
  if (errors.length) {
    throw createError({ statusCode: 400, statusMessage: "Invalid event", data: { errors } })
  }

  // TODO(features): gate recurring events if you flag them

  const now = new Date().toISOString()
  const row = {
    ...dtoToRow(body),
    // Server assigns the id; client-sent id/ownerId are ignored.
    id: randomUUID(),
    ownerId: null,
    isRecurring: !!body.isRecurring,
    allDay: !!body.allDay,
    createdAt: now,
    updatedAt: now,
  } as typeof events.$inferInsert

  const db = useDb()
  const [created] = await db.insert(events).values(row).returning()

  setResponseStatus(event, 201)
  const dto = rowToDto(created)

  // Broadcast to connected clients only after a successful write.
  await broadcastEventChange({ type: "created", event: dto })

  return dto
})

import { eq } from "drizzle-orm"
import { events } from "../../db/schema"
import { dtoToRow, rowToDto, type EventDTO } from "../../utils/eventMapper"
import { validateEventInput } from "../../utils/eventValidation"

// PATCH /api/events/:id — update an event. 404 if it doesn't exist.
export default defineEventHandler(async (event) => {
  const id = getRouterParam(event, "id")
  if (!id) {
    throw createError({ statusCode: 400, statusMessage: "Missing event id" })
  }

  const body = await readBody<Partial<EventDTO>>(event)
  const errors = validateEventInput(body, { partial: true })
  if (errors.length) {
    throw createError({ statusCode: 400, statusMessage: "Invalid event", data: { errors } })
  }

  const db = useDb()
  const existing = await db.select().from(events).where(eq(events.id, id)).limit(1)
  if (existing.length === 0) {
    throw createError({ statusCode: 404, statusMessage: "Event not found" })
  }

  // TODO(auth): require a session; verify the caller owns this event (403 otherwise)

  const updates = {
    ...dtoToRow(body),
    updatedAt: new Date().toISOString(),
  }
  // Never let id/ownerId/createdAt be overwritten via the update path.
  delete (updates as Record<string, unknown>).id
  delete (updates as Record<string, unknown>).ownerId
  delete (updates as Record<string, unknown>).createdAt

  const [updated] = await db.update(events).set(updates).where(eq(events.id, id)).returning()
  const dto = rowToDto(updated)

  await broadcastEventChange({ type: "updated", event: dto })

  return dto
})

import { eq } from "drizzle-orm"
import { events } from "../../db/schema"

// DELETE /api/events/:id — remove an event. 204 on success, 404 if missing.
export default defineEventHandler(async (event) => {
  const id = getRouterParam(event, "id")
  if (!id) {
    throw createError({ statusCode: 400, statusMessage: "Missing event id" })
  }

  const db = useDb()
  const [existing] = await db.select({ id: events.id, ownerId: events.ownerId }).from(events).where(eq(events.id, id)).limit(1)
  if (!existing) {
    throw createError({ statusCode: 404, statusMessage: "Event not found" })
  }

  // TODO(auth): require a session; verify the caller owns this event (403 otherwise)

  const deleted = await db.delete(events).where(eq(events.id, id)).returning({ id: events.id })
  if (deleted.length === 0) {
    throw createError({ statusCode: 404, statusMessage: "Event not found" })
  }

  await broadcastEventChange({ type: "deleted", id, ownerId: existing.ownerId ?? null })

  setResponseStatus(event, 204)
  return null
})
